const state={profile:'Área usuaria',auSubRole:'Jefe',loginLabel:'Área usuaria · Jefe',userName:'María Torres',userInitials:'MT',route:'inbox',resolution:'resBreach'};
let nextCaseNumber = 143;
const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
const isAU=()=>state.profile==='Área usuaria';
const isAuJefe=()=>state.profile==='Área usuaria'&&state.auSubRole==='Jefe';
const isAuEspecialista=()=>state.profile==='Área usuaria'&&state.auSubRole==='Especialista';
const isCmnUa=()=>state.profile==='Unidad de Abastecimiento';
const CMN_ANEXO4_BATCHES={};
