const CMN_STATE_GENERAR_ANEXO4='Generar Anexo 4';
const CMN_STATE_ENVIAR_ANEXO4='Enviar Anexo 4';
const CMN_ANEXO3_DEFAULT_SUPPORT=`Sustento para la aprobación de modificaciones del CMN, al día hábil siguiente de su presentación (numeral 32.7 del artículo 32 de la Directiva): De ser el caso, indicar ellos año(s) que corresponda(n) realizar la inclusión o exclusión de la programación
1/ La información registrada en el presente Anexo corresponde a campos mínimos y obligatorios que pueden ser ampliados por la Entidad del Sector Público.
2/ La información registrada en los campos de "exclusión" e "inclusión" considera la cantidad y/o valor acumulado de todos los años de la programación.
3/ El campo de "cantidad total" se completa solo en el caso de bienes.
4/ La presente información tiene carácter de Declaración Jurada; por lo que, en señal de conformidad y en representación del Área usuaria, se suscribe:`;
const displayRole=()=>state.profile==='Área usuaria'?`${state.profile} · ${state.auSubRole}`:state.profile;
const actorLabel=()=>displayRole();
function applyLoginProfile(selected){const au=AU_LOGIN[selected];if(au){state.profile=au.profile;state.auSubRole=au.auSubRole;state.userName=au.userName;state.userInitials=au.initials;state.loginLabel=selected}else{state.profile=selected;state.auSubRole=null;state.userName='María Torres';state.userInitials='MT';state.loginLabel=selected}}
function updateSessionUi(){$('#sidebarRole').textContent=$('#topbarRole').textContent=displayRole();$$('.sidebar-user b, .profile-chip b').forEach(el=>el.textContent=state.userName);$$('.avatar').forEach(el=>el.textContent=state.userInitials)}
const allowed = id => (ACCESS[id]||[]).includes(state.profile);
const resolutionAllowed = () => RESOLUTIONS.filter(r=>allowed(r.id));
function cmnBatchSourceHiddenFromAu(c){
 if(!c?.cmnBatchId||c.cmnBatchInbox||state.profile!=='Área usuaria')return false;
 return Boolean(c.cmnBatchHiddenFromAu||CMN_ANEXO4_BATCHES[c.cmnBatchId]?.sent);
}
const caseVisible = c => {
 if(c.module==='cmn'&&c.cmnBatchInbox)return state.profile==='Área usuaria';
 if(c.module==='cmn'&&cmnBatchSourceHiddenFromAu(c))return false;
 return c.module==='resolution'?allowed(c.resType):allowed(c.module);
};
const cmnBandejaCases=()=>CASES.filter(c=>{if(c.module!=='cmn'&&c.type!=='CMN')return false;cmnNormalizeCase(c);if(c.cmnBatchInbox)return state.profile==='Área usuaria';if(cmnBatchSourceHiddenFromAu(c))return false;return allowed('cmn')});
const visibleCases = () => CASES.filter(caseVisible);

function init(){
  $('#profileSelect').innerHTML=PROFILES.map(p=>`<option ${p===state.loginLabel?'selected':''}>${p}</option>`).join('');
  $('#loginForm').addEventListener('submit',e=>{e.preventDefault();applyLoginProfile($('#profileSelect').value);enterApp()});
  $('#logoutBtn').addEventListener('click',logout); $('#profileButton').addEventListener('click',logout);
  $('#menuBtn').addEventListener('click',()=>toggleSidebar(true)); $('#sidebarClose').addEventListener('click',()=>toggleSidebar(false));
  $('#sidebarBackdrop').addEventListener('click',()=>toggleSidebar(false));
  document.addEventListener('click',globalClick);
}

function enterApp(){
  $('#loginView').hidden=true;$('#appView').hidden=false;
  updateSessionUi();
  $$('[data-requires]').forEach(el=>el.hidden=!allowed(el.dataset.requires));
  state.route='inbox';buildNav();render();showToast(`Sesión SSO iniciada como ${displayRole()}`);
}
function logout(){ $('#appView').hidden=true;$('#loginView').hidden=false;togglePanel(false); }
function toggleSidebar(open){$('#sidebar').classList.toggle('open',open);$('#sidebarBackdrop').hidden=!open}
function togglePanel(force){const panel=$('#notificationPanel');if(!panel)return;panel.hidden=force===undefined?!panel.hidden:!force}

function globalClick(e){
  const addCmnItem=e.target.closest('#addCmnItem');if(addCmnItem){const body=$('#cmnItemsBody');body.insertAdjacentHTML('beforeend',cmnItemRow());refreshCmnItemRows();body.querySelector('tr:last-child input')?.focus();return}
  const removeCmnItem=e.target.closest('.cmn-remove-item');if(removeCmnItem){const rows=$$('#cmnItemsBody tr');if(rows.length===1){showToast('Debe conservar al menos un ítem');return}removeCmnItem.closest('tr').remove();refreshCmnItemRows();return}
  const addSigaOrder=e.target.closest('.siga-add-order');if(addSigaOrder){addSigaOrderFromPicker(addSigaOrder.closest('.siga-order-editor'));return}
  const removeSigaOrder=e.target.closest('.siga-remove-order');if(removeSigaOrder){const editor=removeSigaOrder.closest('.siga-order-editor');removeSigaOrder.closest('tr').remove();refreshSigaOrderTable(editor);return}
  const addProposal=e.target.closest('#addAnnex5Proposal');if(addProposal){addAnnex5ProposalFromCard();return}
  const removeProposal=e.target.closest('.annex5-remove-proposal');if(removeProposal){removeProposal.closest('tr').remove();refreshAnnex5ProposalTable();return}
  const resAction=e.target.closest('[data-res-action]'); if(resAction){e.stopPropagation();if($('#caseDialog').open)$('#caseDialog').close();handleResolutionAction(resAction.dataset.resAction,resAction.dataset.id);return}
  const modAction=e.target.closest('[data-mod-action]'); if(modAction){e.stopPropagation();if($('#caseDialog').open)$('#caseDialog').close();handleModificationAction(modAction.dataset.modAction,modAction.dataset.id);return}
  const execAction=e.target.closest('[data-exec-action]'); if(execAction){e.stopPropagation();if($('#caseDialog').open)$('#caseDialog').close();handleExecutionAction(execAction.dataset.execAction,execAction.dataset.id);return}
  const payAction=e.target.closest('[data-pay-action]'); if(payAction){e.stopPropagation();if($('#caseDialog').open)$('#caseDialog').close();handlePaymentAction(payAction.dataset.payAction,payAction.dataset.id);return}
  const reqAction=e.target.closest('[data-req-action]'); if(reqAction){e.stopPropagation();if($('#caseDialog').open)$('#caseDialog').close();handleRequirementAction(reqAction.dataset.reqAction,reqAction.dataset.id);return}
  const cmnBulk=e.target.closest('[data-cmn-bulk]');if(cmnBulk){e.stopPropagation();handleCmnBulkAction(cmnBulk.dataset.cmnBulk);return}
  const cmnSelect=e.target.closest('[data-cmn-select]');if(cmnSelect){e.stopPropagation();updateCmnBulkToolbar();return}
  if(e.target.closest('#cmnSelectAll')){e.stopPropagation();const checked=e.target.checked;$$('[data-cmn-select]').forEach(cb=>{cb.checked=checked});updateCmnBulkToolbar();return}
  const cmnAction=e.target.closest('[data-cmn-action]'); if(cmnAction){e.stopPropagation();if($('#caseDialog').open)$('#caseDialog').close();handleCmnAction(cmnAction.dataset.cmnAction,cmnAction.dataset.id);return}
  const edit=e.target.closest('[data-edit]'); if(edit){e.stopPropagation();editRecord(edit.dataset.edit);return}
  const del=e.target.closest('[data-delete]'); if(del){e.stopPropagation();deleteRecord(del.dataset.delete);return}
  const route=e.target.closest('[data-route]'); if(route){navigate(route.dataset.route,route.dataset.sub);return}
  const toast=e.target.closest('[data-toast]'); if(toast){showToast(toast.dataset.toast);return}
  const row=e.target.closest('tr[data-case]');if(row&&!e.target.closest('[data-cmn-select],[data-cmn-bulk],[data-cmn-action],[data-edit],[data-delete],.workflow-actions,.table-action,button,a,input,select,textarea,label')){openCase(row.dataset.case);return}
  const tab=e.target.closest('[data-tab]'); if(tab){$$('.tab').forEach(x=>x.classList.remove('active'));tab.classList.add('active');showToast(`Vista “${tab.textContent.trim()}” seleccionada`);return}
  const exp=e.target.closest('[data-export]'); if(exp){exportReport(exp.dataset.export);return}
  const action=e.target.closest('[data-action]'); if(action){handleAction(action.dataset.action);return}
}

function buildNav(){
  const moduleItems=Object.entries(MODULES).filter(([id])=>allowed(id)).map(([id,m])=>navItem(id,m.icon,m.label)).join('');
  const resolutions=resolutionAllowed();
  const resolutionNav=resolutions.length?navItem('resolution','⚑','Resolución'):'';
  $('#mainNav').innerHTML=`
    <p class="nav-section">Trabajo</p>${navItem('inbox','▣','Mi bandeja')}
    <p class="nav-section">Procesos</p>${moduleItems}${resolutionNav}`;
}
function navItem(id,icon,label){return `<button class="nav-item ${state.route===id?'active':''}" data-route="${id}"><span class="nav-icon">${icon}</span><span>${label}</span></button>`}
function navigate(route,sub){
  if(MODULES[route]&&!allowed(route)){showToast('Tu perfil no tiene acceso a este módulo');return}
  if(route==='resolution'&&!resolutionAllowed().length){showToast('Tu perfil no tiene acceso a Resolución');return}
  state.route=route;toggleSidebar(false);togglePanel(false);buildNav();render();window.scrollTo({top:0,behavior:'smooth'});
}

function render(){
  const views={home:renderHome,inbox:renderInbox,files:renderFiles,alerts:renderAlerts,reports:renderReports,audit:renderAudit,resolution:renderResolution};
  const fn=views[state.route]||(MODULES[state.route]?()=>renderModule(state.route):renderHome);
  $('#mainContent').innerHTML=fn();
  const title=state.route==='home'?'Resumen de gestión':state.route==='resolution'?'Resolución contractual':MODULES[state.route]?.label||({inbox:'Mi bandeja',files:'Expedientes',alerts:'Alertas y notificaciones',reports:'Reportes e indicadores',audit:'Auditoría'}[state.route]);
  $('#pageTitle').textContent=title;$('#breadcrumb').textContent=`SIGCM / ${title}`;
}

function pageHead(title,desc,actions=''){return `<div class="page-head"><div><span class="eyebrow">${displayRole()}</span><h2>${title}</h2><p>${desc}</p></div><div class="page-actions">${actions}</div></div>`}
function stats(){return `<div class="stats-grid">
  ${stat('Tareas pendientes','12','↗','+3 esta semana')}${stat('En plazo','28','✓','92% de cumplimiento')}${stat('Próximas a vencer','4','!','Requieren atención','warn')}${stat('Monto gestionado','S/ 1.2 M','S/','Acumulado 2026')}
  </div>`}
function stat(label,value,icon,trend,kind=''){return `<article class="stat-card"><div class="stat-head"><span>${label}</span><span class="stat-icon">${icon}</span></div><div class="stat-value">${value}</div><span class="trend ${kind?'trend--warn':''}">${trend}</span></article>`}

function renderHome(){
  const permitted=Object.entries(MODULES).filter(([id])=>allowed(id)).map(([,m])=>m.label);if(resolutionAllowed().length)permitted.push('Resolución');
  const recent=visibleCases().slice(0,4);
  return `${pageHead('Buenos días, María','Esta es la situación actual de los procesos disponibles para tu perfil.',`<button class="btn btn--outline" data-export="pdf">Exportar resumen</button><button class="btn btn--primary" data-route="inbox">Ver mis tareas</button>`)}${stats()}
  <div class="dashboard-grid"><section class="card"><div class="card-head"><div><h3>Actividad reciente</h3><p>Últimos movimientos de tus expedientes</p></div><button class="link-button" data-route="files">Ver todo</button></div><div class="activity-list">
    ${recent.length?recent.map((c,i)=>activity(i===0?'✓':i===1?'↗':i===2?'!':'◇',c.state,`${c.id} · ${c.title}`,['Hace 18 min','Hace 42 min','Hace 2 h','Ayer'][i])).join(''):'<p class="muted">No hay actividad para los módulos habilitados.</p>'}
  </div></section><aside class="card"><div class="card-head"><div><h3>Plazos críticos</h3><p>Prioridad por vencimiento</p></div></div><div class="deadline-list">
    ${deadline('Subsanar requerimiento','EXP-2026-00142','6 horas',82)}${deadline('Emitir informe técnico','EXP-2026-00127','1 día',63)}${deadline('Validar entregable','EXP-2026-00138','2 días',46)}
  </div></aside></div>
  <section class="card" style="margin-top:18px"><div class="card-head"><div><h3>Accesos habilitados</h3><p>Visibilidad calculada para el perfil ${displayRole()}</p></div></div><div class="filters">${permitted.map(x=>`<span class="badge badge--info">${x}</span>`).join('')||'<span class="muted">Sin módulos de proceso habilitados.</span>'}</div></section>`;
}
function activity(icon,title,sub,time){return `<div class="activity"><span class="activity-icon">${icon}</span><span><b>${title}</b><small>${sub}</small></span><time>${time}</time></div>`}
function deadline(title,id,time,p){return `<div class="deadline"><b>${title}</b><small>${id}</small><div class="remaining">Vence en ${time}</div><div class="progress"><span style="width:${p}%"></span></div></div>`}

function renderInbox(){return `${pageHead('Mi bandeja','Tareas pendientes de atención según tu perfil y etapa del proceso.',`<button class="btn btn--outline" data-export="excel">Exportar Excel</button>`)}${taskToolbar()}${caseTable(visibleCases().slice(0,5),true)}`}
function renderFiles(){return `${pageHead('Expedientes','Consulta consolidada de contratos menores y su trazabilidad documental, limitada a tus accesos.',`<button class="btn btn--outline" data-export="excel">Exportar Excel</button><button class="btn btn--outline" data-export="pdf">Exportar PDF</button>`)}${taskToolbar()}${caseTable(visibleCases(),false)}`}
function taskToolbar(){return `<div class="toolbar"><div class="filters"><input class="filter-control" placeholder="Buscar por expediente"><select class="filter-control"><option>Todos los estados</option><option>En plazo</option><option>Observado</option><option>Vencido</option></select><select class="filter-control"><option>Todos los tipos</option><option>Bien</option><option>Servicio</option><option>Consultoría</option><option>Locación</option></select></div><button class="btn btn--soft" data-toast="Filtros actualizados.">Aplicar filtros</button></div>`}
function caseTable(items,tasks){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Expediente</th><th>Contratación</th><th>${tasks?'Tarea / Estado':'Estado actual'}</th><th>Responsable</th><th>Monto</th><th>Plazo</th><th>Acciones</th></tr></thead><tbody>${items.length?items.map(c=>`<tr data-case="${c.id}"><td><span class="case-id">${c.id}</span></td><td class="case-main"><b>${c.title}</b><small>${c.type} · ${c.order}</small></td><td><span class="badge badge--${c.status}">${c.state}</span></td><td>${c.owner}</td><td>${c.amount}</td><td>${c.due}</td><td><div class="workflow-actions">${genericActionButtons(c)}</div></td></tr>`).join(''):`<tr><td colspan="7"><div class="empty-state"><div class="empty-icon">◇</div><h3>Sin registros</h3><p class="muted">Usa “Nuevo registro” para agregar el primero.</p></div></td></tr>`}</tbody></table></div>`}
function moduleWorkflowButtons(c){
 if(c.module==='cmn')return cmnActionButtons(c);
 if(c.module==='requirement')return requirementActionButtons(c);
 if(c.module==='payment')return paymentActionButtons(c);
 if(c.module==='execution')return executionActionButtons(c);
 if(c.module==='modification')return modificationActionButtons(c);
 if(c.module==='resolution')return resolutionActionButtons(c);
 return '';
}
function genericActionButtons(c){
 const view=`<button class="table-action" data-case="${c.id}" title="Ver expediente" aria-label="Ver ${c.id}">⌕</button>`;
 const workflow=moduleWorkflowButtons(c);
 if(workflow)return `${workflow}${view}`;
 return `${view}<button class="table-action" data-edit="${c.id}" title="Editar registro" aria-label="Editar ${c.id}">✎</button><button class="table-action table-action--danger" data-delete="${c.id}" title="Eliminar registro" aria-label="Eliminar ${c.id}">×</button>`;
}

