function cmnTableRows(items=[]){return [...items,...Array(Math.max(0,5-items.length)).fill({})].map(x=>`<tr><td>${annexText(x.code,'')}</td><td>${annexText(x.description,'')}</td><td>${annexText(x.unit,'')}</td><td>${annexText(x.exclQty,'')}</td><td>${annexText(x.exclValue,'')}</td><td>${annexText(x.inclQty,'')}</td><td>${annexText(x.inclValue,'')}</td></tr>`).join('')}
function cmnSignatureBlock(sig,label,name){return `<div class="cmn-sign-line">${sig?`<b>✓ FIRMADO DIGITALMENTE</b><small>${escapeHtml(sig.name)} · ${escapeHtml(sig.date)}<br>SHA-256: ${escapeHtml(sig.hash)}</small>`:'<span></span>'}<strong>${escapeHtml(name||label)}</strong><small>${label}</small></div>`}
function renderCmnAnexo3(c){const a=c.cmnAnexo3||{};return `<div class="annex-document"><article class="annex-page cmn-landscape"><div class="annex-page-number">Fecha ${annexText(a.date,'')} · Página 1/1</div><div class="cmn-doc-title">ANEXO N.° 03: SOLICITUD DE MODIFICACIÓN DEL CUADRO MULTIANUAL DE NECESIDADES N.° ${annexText(a.requestNumber,'')}</div><p><b>Área usuaria:</b> ${annexText(a.userArea,'')}<br><b>Fecha:</b> ${annexText(a.date,'')}</p><table class="cmn-doc-table"><thead><tr><th rowspan="2">Código</th><th rowspan="2">Descripción</th><th rowspan="2">Unidad de medida</th><th colspan="2">EXCLUSIÓN</th><th colspan="2">INCLUSIÓN</th></tr><tr><th>Cantidad total</th><th>Valor total S/</th><th>Cantidad total</th><th>Valor total S/</th></tr></thead><tbody>${cmnTableRows(a.items)}</tbody></table><p><b>Sustento:</b> ${annexText(a.support,'')}</p>${cmnSignatureBlock(c.cmnAnexo3Signature,'Firma: Responsable del Área usuaria',a.signerName)}</article></div>`}
function renderCmnAnexo4(c){const a=c.cmnAnexo4||{};return `<div class="annex-document"><article class="annex-page cmn-landscape"><div class="annex-page-number">Fecha ${annexText(a.requestDate,'')} · Página 1/1</div><div class="cmn-doc-title">ANEXO N.° 04: APROBACIÓN DE MODIFICACIONES AL CUADRO MULTIANUAL DE NECESIDADES N.° ${annexText(a.requestNumber,'')}</div><p><b>Entidad del Sector Público:</b> ${annexText(a.entity,'')}<br><b>N.° de identificación:</b> ${annexText(a.identification,'')}</p><table class="cmn-doc-table"><thead><tr><th>Fecha de solicitud</th><th>N.° de solicitud</th><th>Código ítem</th><th>Descripción</th><th>Unidad</th><th>Exclusión cantidad</th><th>Exclusión valor S/</th><th>Inclusión cantidad</th><th>Inclusión valor S/</th></tr></thead><tbody>${[...(a.items||[]),...Array(Math.max(0,5-(a.items||[]).length)).fill({})].map(x=>`<tr><td>${annexText(a.requestDate,'')}</td><td>${annexText(a.requestNumber,'')}</td><td>${annexText(x.code,'')}</td><td>${annexText(x.description,'')}</td><td>${annexText(x.unit,'')}</td><td>${annexText(x.exclQty,'')}</td><td>${annexText(x.exclValue,'')}</td><td>${annexText(x.inclQty,'')}</td><td>${annexText(x.inclValue,'')}</td></tr>`).join('')}</tbody></table><div class="cmn-dual-sign">${cmnSignatureBlock(c.cmnAnexo4Signature,'Firma 1: Responsable de la Oficina de Abastecimiento',a.supplySigner)}${cmnSignatureBlock(c.cmnAnexo4Signature,'Firma 2: Máxima autoridad administrativa',a.authoritySigner)}</div></article></div>`}
function openCmnDocumentViewer(c,kind){const is3=kind==='anexo3';if(!is3&&c.cmnBatchId){openCmnBulkAnexo4ViewerByBatch(c.cmnBatchId);return}const doc=is3?c.cmnAnexo3:c.cmnAnexo4,sig=is3?c.cmnAnexo3Signature:getCmnAnexo4Signature(c);if(!doc){showToast(`Primero genere el Anexo ${is3?'3':'4'}`);return}const canSignAnexo3=is3&&isAuJefe()&&!sig&&(c.cmnStage==='anexo3_draft'||(c.cmnStage==='au_jefe_pending'&&c.auPendingAction==='sign_cmn_anexo3'));let action='';if(canSignAnexo3)action=`<button class="btn btn--primary" data-cmn-action="sign_cmn_anexo3" data-id="${c.id}">Firmar digitalmente</button>`;else if(is3&&isAuEspecialista()&&c.cmnStage==='anexo3_draft'&&!sig)action=`<span class="muted viewer-hint">La firma digital la realiza el Jefe del Área usuaria.</span>`;else if(!is3&&state.profile==='Unidad de Abastecimiento'&&c.cmnStage==='anexo4_draft'&&!c.cmnBatchId)action=`<button class="btn btn--primary" data-cmn-action="sign_cmn_anexo4" data-id="${c.id}">Firmar digitalmente</button>`;else if(!is3&&state.profile==='Unidad de Abastecimiento'&&c.cmnStage==='anexo4_signed'&&!c.cmnBatchId&&sig)action=`<button class="btn btn--primary" data-cmn-action="send_anexo4" data-id="${c.id}">Enviar Anexo 4 al Área usuaria</button>`;$('#caseDialogBody').innerHTML=`<div class="case-detail-head annex-view-head"><div><span class="eyebrow">Documento CMN generado</span><h2>Anexo N.° ${is3?'03':'04'} · ${c.id}</h2><p>${sig?'Firmado digitalmente':'Borrador pendiente de firma'}</p></div><span class="badge badge--${sig?'success':'warning'}">${sig?'Firmado':'Borrador'}</span></div><div class="case-detail-body annex-viewer"><div class="annex-view-toolbar"><button class="btn btn--outline" data-export="pdf">Imprimir / Guardar PDF</button>${action}</div>${is3?renderCmnAnexo3(c):renderCmnAnexo4(c)}</div>`;$('#caseDialog').showModal()}
function signCmnDocument(c,kind){const is3=kind==='anexo3';if(is3&&!isAuJefe()){showToast('Sólo el Jefe del Área usuaria puede firmar el Anexo 3');return}const doc=is3?c.cmnAnexo3:c.cmnAnexo4,now=new Date();const signature={name:is3?state.userName:doc.supplySigner,role:is3?'Responsable del Área usuaria':doc.signerRole||'Responsable de la Oficina de Abastecimiento',date:now.toLocaleString('es-PE'),hash:fakeDocumentHash(`${kind}|${c.id}|${JSON.stringify(doc)}|${now.toISOString()}`)};if(is3){c.cmnAnexo3Signature=signature;if(c.auPendingAction==='sign_cmn_anexo3')delete c.auPendingAction}else c.cmnAnexo4Signature=signature;applyCmnTransition(c,is3?'anexo3_signed':'anexo4_signed',is3?'Anexo 3 firmado, pendiente de envío':CMN_STATE_ENVIAR_ANEXO4,is3?'Área usuaria · Jefe':'Unidad de Abastecimiento',`Anexo ${is3?'3':'4'} firmado digitalmente`);openCmnDocumentViewer(c,kind)}

function openAnexo4Form(c){
 const a=c.anexo4||{};const value=(key,fallback='')=>escapeHtml(a[key]||fallback);const today=new Date().toISOString().slice(0,10);
 $('#caseDialogBody').innerHTML=`<div class="case-detail-head"><span class="eyebrow">Unidad de Abastecimiento</span><h2>Completar Anexo N.° 4</h2><p>Términos de Referencia para la contratación de consultorías · ${c.id}</p></div><div class="case-detail-body"><div class="sso-note"><span>i</span><p><b>Antes de generar el documento</b><br>Complete los campos obligatorios de las páginas 38 a 41 de la Directiva N.° 002-2026-ANIN. Las cláusulas normativas se incorporan automáticamente.</p></div><form id="anexo4Form" class="form-grid annex-data-form">
 <fieldset class="form-field--full annex-form-section"><legend>Datos generales</legend><div class="form-grid"><div class="form-field"><label>Fecha</label><input name="date" type="date" required value="${value('date',today)}"></div><div class="form-field"><label>Unidad de Organización</label><input name="orgUnit" required value="${value('orgUnit')}"></div><div class="form-field"><label>Actividad Operativa</label><input name="operativeActivity" required value="${value('operativeActivity')}"></div><div class="form-field"><label>Meta Presupuestaria</label><input name="budgetGoal" required value="${value('budgetGoal')}"></div><div class="form-field form-field--full"><label>Denominación de la contratación</label><input name="denomination" required value="${value('denomination',c.title)}"></div></div></fieldset>
 <fieldset class="form-field--full annex-form-section"><legend>I - III. Finalidad y servicio</legend><div class="form-grid"><div class="form-field form-field--full"><label>I. Finalidad pública</label><textarea name="publicPurpose" required>${value('publicPurpose')}</textarea></div><div class="form-field form-field--full"><label>II. Objetivo de la contratación</label><textarea name="objective" required>${value('objective')}</textarea></div><div class="form-field form-field--full"><label>III. Alcances y descripción del servicio</label><textarea name="scope" required>${value('scope')}</textarea></div></div></fieldset>
 <fieldset class="form-field--full annex-form-section"><legend>IV. Perfil del consultor</legend><div class="form-grid"><div class="form-field form-field--full"><label>4.1 Requisitos del consultor</label><textarea name="consultantRequirements" required placeholder="Formación, colegiatura, capacitación y experiencia requerida">${value('consultantRequirements')}</textarea></div><div class="form-field"><label>4.2.1 Equipamiento</label><textarea name="equipment" placeholder="De corresponder">${value('equipment')}</textarea></div><div class="form-field"><label>4.2.2 Infraestructura estratégica</label><textarea name="infrastructure" placeholder="De corresponder">${value('infrastructure')}</textarea></div><div class="form-field"><label>4.2.3 Personal</label><textarea name="personnel" placeholder="De corresponder">${value('personnel')}</textarea></div><div class="form-field"><label>4.2.4 Reglamentos y normas</label><textarea name="regulations" placeholder="De corresponder">${value('regulations')}</textarea></div><div class="form-field"><label>4.2.5 Seguros</label><textarea name="insurance" placeholder="Cobertura, plazo, monto y oportunidad">${value('insurance')}</textarea></div><div class="form-field"><label>4.2.6 Prestaciones accesorias</label><textarea name="accessoryServices" placeholder="De corresponder">${value('accessoryServices')}</textarea></div></div></fieldset>
 <fieldset class="form-field--full annex-form-section"><legend>V - VIII. Ejecución, entregables y pago</legend><div class="form-grid"><div class="form-field"><label>5.1 Lugar de prestación</label><input name="servicePlace" required value="${value('servicePlace')}"></div><div class="form-field"><label>5.2 Plazo de ejecución</label><input name="executionTerm" required value="${value('executionTerm')}"></div><div class="form-field form-field--full"><label>VI. Entregables</label><textarea name="deliverables" required>${value('deliverables')}</textarea></div><div class="form-field form-field--full"><label>VII. Área usuaria que emite la conformidad</label><input name="conformityArea" required value="${value('conformityArea')}"></div><div class="form-field form-field--full"><label>VIII. Forma y condiciones de pago</label><textarea name="paymentTerms" required placeholder="Indicar entregables, letras y número; pago único o armadas">${value('paymentTerms')}</textarea></div></div></fieldset>
 <fieldset class="form-field--full annex-form-section"><legend>IX - XV. Condiciones contractuales</legend><div class="form-grid"><div class="form-field form-field--full"><label>X. Responsabilidad por asignación de bienes</label><textarea name="assignedAssets" placeholder="De corresponder">${value('assignedAssets')}</textarea></div><div class="form-field form-field--full"><label>12.2 Otras penalidades</label><textarea name="otherPenalties" placeholder="Situaciones, condiciones, verificación y monto o porcentaje, de corresponder">${value('otherPenalties')}</textarea></div><div class="form-field"><label>Nombres y apellidos del firmante</label><input name="signerName" required value="${value('signerName','María Torres')}"></div><div class="form-field"><label>Cargo</label><input name="signerRole" required value="${value('signerRole','Especialista de Abastecimiento')}"></div><div class="form-field form-field--full"><label>Nombre del Área usuaria</label><input name="userArea" required value="${value('userArea')}"></div></div></fieldset>
 <div class="form-actions"><button type="button" class="btn btn--outline" data-close-record>Cancelar</button><button class="btn btn--primary">Generar vista previa del Anexo 4</button></div></form></div>`;
 $('[data-close-record]').addEventListener('click',()=>$('#caseDialog').close());$('#anexo4Form').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.currentTarget);c.anexo4=Object.fromEntries([...d.entries()].map(([k,v])=>[k,String(v)]));c.anexo4.template='Directiva N.° 002-2026-ANIN · páginas 38-41';c.anexo4.documentId=`ANX4-${c.id.replace('EXP-','')}`;$('#caseDialog').close();applyCmnTransition(c,'anexo4_draft','Anexo 4 generado, pendiente de firma','Unidad de Abastecimiento','Anexo 4 generado con los TDR de consultoría');openAnexo4Viewer(c)});$('#caseDialog').showModal()
}
function annexText(value,fallback='No corresponde'){return escapeHtml(value||fallback).replace(/\n/g,'<br>')}
function annexSection(number,title,body,required=true){return `<section class="annex-section"><h4>${number}. &nbsp;${title} <small>${required?'(obligatorio)':'(de corresponder)'}</small></h4><div class="annex-section-body">${body}</div></section>`}
function annexHeader(page,total,a){return `<div class="annex-brand"><b><span>AN</span>IN</b><i></i></div>${page===1?`<div class="annex-title"><b>ANEXO N.° 4</b><strong>TÉRMINOS DE REFERENCIA PARA LA CONTRATACIÓN DE CONSULTORÍAS</strong></div>`:''}<div class="annex-page-number">Página ${page} de ${total}</div>`}
function annexSignature(c){return c.anexo4Signature?`<div class="digital-signature"><span>✓</span><p><b>Firmado digitalmente</b><br>${escapeHtml(c.anexo4Signature.name)} · ${escapeHtml(c.anexo4Signature.role)}<br>${escapeHtml(c.anexo4Signature.date)}<br>SHA-256: ${escapeHtml(c.anexo4Signature.hash)}</p></div>`:''}
function renderAnexo4Document(c){const a=c.anexo4||{};const fixedConformity=`La conformidad se emite en un plazo máximo de siete (07) días, contabilizados desde el día siguiente de recibido el entregable, salvo que se requieran pruebas para verificar el cumplimiento de la obligación.`;const fixedPayment=`Previa presentación del entregable y emisión de la conformidad, el pago se efectuará según las condiciones registradas. El pago incluye los impuestos de ley y todo costo o retención aplicable. La Entidad pagará dentro de los diez (10) días calendario siguientes de otorgada la conformidad, cuando se verifiquen las condiciones establecidas.`;const fixedResponsibility=`El/la contratista es responsable por la calidad ofrecida y por los vicios ocultos del servicio por un plazo no menor de un (1) año desde la conformidad.`;const fixedConfidentiality=`El contratista no deberá divulgar, revelar, entregar o poner a disposición de terceros la información proporcionada por la Entidad, durante y después de concluida la vigencia del documento, salvo autorización expresa.`;const fixedPenalty=`La suma de las penalidades por mora y otras penalidades no puede exceder el 10% del monto del contrato menor. La penalidad por mora se aplica automáticamente por cada día de atraso injustificado y se calcula conforme a la Directiva.`;const fixedResolution=`La ANIN puede resolver el contrato por incumplimiento, caso fortuito o fuerza mayor, hecho sobreviniente, incumplimiento de la cláusula anticorrupción, documentación falsa o inexacta, o cuando las penalidades excedan el 10%. Puede resolverse total o parcialmente por mutuo acuerdo, previa opinión del Área usuaria.`;const fixedAnti=`El proveedor declara no haber ofrecido ni efectuado pagos o beneficios ilegales y se obliga a actuar con honestidad, probidad, veracidad e integridad, comunicar cualquier conducta ilícita y adoptar medidas para evitar actos de corrupción.`;const fixedDisputes=`Las controversias sobre validez, interpretación, ejecución, terminación o eficacia se resuelven mediante conciliación conforme a la Ley General de Contrataciones Públicas y su Reglamento.`;
 return `<div class="annex-document">
 <article class="annex-page">${annexHeader(1,4,a)}<table class="annex-meta"><tr><th>Fecha</th><td>${annexText(a.date,'')}</td></tr><tr><th>Unidad de Organización</th><td>${annexText(a.orgUnit,'')}</td></tr><tr><th>Actividad Operativa</th><td>${annexText(a.operativeActivity,'')}</td></tr><tr><th>Meta Presupuestaria</th><td>${annexText(a.budgetGoal,'')}</td></tr><tr><th>Denominación de la contratación</th><td>${annexText(a.denomination,c.title)}</td></tr></table>${annexSection('I','FINALIDAD PÚBLICA',annexText(a.publicPurpose,''))}${annexSection('II','OBJETIVO DE LA CONTRATACIÓN',annexText(a.objective,''))}${annexSection('III','ALCANCES Y DESCRIPCIÓN DEL SERVICIO',annexText(a.scope,''))}${annexSection('IV','PERFIL DEL CONSULTOR',`<b>4.1 Requisitos del consultor</b><p>${annexText(a.consultantRequirements,'')}</p><b>4.2 Recursos provistos por el consultor</b><ul><li><b>Equipamiento:</b> ${annexText(a.equipment)}</li><li><b>Infraestructura estratégica:</b> ${annexText(a.infrastructure)}</li><li><b>Personal:</b> ${annexText(a.personnel)}</li><li><b>Reglamentos y normas:</b> ${annexText(a.regulations)}</li><li><b>Seguros:</b> ${annexText(a.insurance)}</li><li><b>Prestaciones accesorias:</b> ${annexText(a.accessoryServices)}</li></ul>`)}${annexSignature(c)}</article>
 <article class="annex-page">${annexHeader(2,4,a)}${annexSection('V','LUGAR Y PLAZO DE EJECUCIÓN',`<p><b>5.1 Lugar de prestación:</b> ${annexText(a.servicePlace,'')}</p><p><b>5.2 Plazo:</b> ${annexText(a.executionTerm,'')}</p><p><b>5.3 Presentación:</b> Los entregables, comprobantes y documentos se presentan mediante la Mesa de Partes virtual o presencial de la ANIN.</p>`)}${annexSection('VI','ENTREGABLES',annexText(a.deliverables,''))}${annexSection('VII','CONFORMIDAD',`<p><b>Área usuaria que emite la conformidad:</b> ${annexText(a.conformityArea,'')}</p><p>${fixedConformity}</p>`)}${annexSection('VIII','FORMA Y CONDICIONES DE PAGO',`<p>${annexText(a.paymentTerms,'')}</p><p>${fixedPayment}</p>`)}${annexSection('IX','RESPONSABILIDAD DEL/DE LA CONTRATISTA',fixedResponsibility)}${annexSection('X','RESPONSABILIDAD POR LA ASIGNACIÓN DE BIENES',annexText(a.assignedAssets),false)}${annexSignature(c)}</article>
 <article class="annex-page">${annexHeader(3,4,a)}${annexSection('XI','CONFIDENCIALIDAD',fixedConfidentiality)}${annexSection('XII','PENALIDADES',`<p>${fixedPenalty}</p><p><b>12.1 Penalidad por mora:</b> Penalidad diaria = (0.10 × monto) / (0.40 × plazo).</p><p><b>12.2 Otras penalidades:</b> ${annexText(a.otherPenalties)}</p>`)}${annexSection('XIII','RESOLUCIÓN CONTRACTUAL',fixedResolution)}${annexSignature(c)}</article>
 <article class="annex-page">${annexHeader(4,4,a)}${annexSection('XIV','CLÁUSULA ANTICORRUPCIÓN',fixedAnti)}${annexSection('XV','SOLUCIÓN DE CONTROVERSIAS',fixedDisputes)}<div class="annex-manual-sign"><b>(Firma digital o manuscrita)</b><strong>${annexText(a.signerName,'')}</strong><span>${annexText(a.signerRole,'')}</span><span>${annexText(a.userArea,'')}</span></div>${annexSignature(c)}</article></div>`
}
function openAnexo4Viewer(c){if(!c.anexo4){showToast('Primero complete los datos del Anexo 4');return}const signed=Boolean(c.anexo4Signature);let action='';if(state.profile==='Unidad de Abastecimiento'&&c.cmnStage==='anexo4_draft')action=`<button class="btn btn--primary" data-cmn-action="confirm_sign_anexo4" data-id="${c.id}">Firmar digitalmente</button>`;$('#caseDialogBody').innerHTML=`<div class="case-detail-head annex-view-head"><div><span class="eyebrow">Documento generado</span><h2>Anexo N.° 4 · ${c.id}</h2><p>Vista previa tipo PDF/Word · ${signed?'firmado digitalmente':'borrador pendiente de firma'}</p></div><span class="badge badge--${signed?'success':'warning'}">${signed?'Firmado':'Borrador'}</span></div><div class="case-detail-body annex-viewer"><div class="annex-view-toolbar"><button class="btn btn--outline" data-export="pdf">Imprimir / Guardar PDF</button><button class="btn btn--outline" data-toast="Documento Word simulado preparado para descarga.">Descargar Word</button>${action}</div>${renderAnexo4Document(c)}</div>`;$('#caseDialog').showModal()}
function signAnexo4(c){const now=new Date();c.anexo4Signature={name:c.anexo4.signerName,role:c.anexo4.signerRole,date:now.toLocaleString('es-PE'),hash:fakeDocumentHash(`${c.id}|${JSON.stringify(c.anexo4)}|${now.toISOString()}`)};applyCmnTransition(c,'anexo4_signed','Anexo 4 firmado, pendiente de envío','Unidad de Abastecimiento','Anexo 4 firmado digitalmente');openAnexo4Viewer(c)}
function fakeDocumentHash(value){let h=2166136261;for(let i=0;i<value.length;i++){h^=value.charCodeAt(i);h=Math.imul(h,16777619)}return `${(h>>>0).toString(16).padStart(8,'0')}b4c2e91a7d30f6c85e42a109`}

function renderRequirementModule(){
 const m=MODULES.requirement;const records=CASES.filter(c=>c.module==='requirement');const canCreate=state.profile==='Área usuaria';
 const guide=state.profile==='Área usuaria'?(isAuJefe()?['Aprueba y remite requerimientos del Área usuaria. Recibe derivaciones del especialista.','Aprobar y remitir']:['Formula requerimientos y documentos técnicos. Deriva al Jefe para envío a otras áreas.','Elaborar y derivar al Jefe']):{
  'Oficina de administración':['Recepciona los requerimientos cuya DEC es la Unidad de Abastecimiento y los deriva el mismo día.','Recepcionar y derivar a la UA'],
  'DAI':['Recibe directamente los requerimientos asignados a DAI, los revisa y conduce la contratación.','Revisar como dependencia competente'],
  'Unidad de Abastecimiento':['Actúa como DEC para bienes, servicios y consultorías ordinarias; revisa, conduce la indagación, perfecciona y notifica.','Conducir la contratación'],
  'Planeamiento y Presupuesto':['Recepciona, aprueba y remite la certificación o previsión presupuestal.','Atender CCP / previsión']
 }[state.profile];
 return `${pageHead('Requerimiento a notificación',m.subtitle,canCreate?`<button class="btn btn--primary" data-action="new-requirement">+ Nuevo requerimiento</button>`:`<span class="badge badge--neutral">Perfil de atención: sin registro inicial</span>`)}
 <div class="module-hero"><section class="process-card"><span class="eyebrow eyebrow--light">Flujo por perfil</span><h2>${guide[1]}</h2><p>${guide[0]}</p><div class="process-stages">${m.stages.map((s,i)=>`<div class="stage ${i<2?'done':i===2?'active':''}"><span></span><small>${s}</small></div>`).join('')}</div></section><aside class="quick-card"><h3>Responsabilidades del perfil</h3><div class="role-checks">${requirementRoleChecks().map(x=>`<div><span>✓</span>${x}</div>`).join('')}</div></aside></div>
 <section class="card"><div class="card-head"><div><h3>Bandeja del proceso</h3><p>Cada acción se habilita por perfil, dependencia competente y etapa.</p></div><span class="badge badge--info">${records.length} expediente(s)</span></div>${requirementTable(records)}</section>`
}
function requirementRoleChecks(){if(isAuJefe())return ['Aprobar derivaciones del especialista','Remitir requerimientos a OA o DAI','Subsanar u otorgar no objeción','Atender consultas y validar ofertas técnicas'];if(isAuEspecialista())return ['Identificar necesidad y disponibilidad presupuestal','Adjuntar CMN, pedido SIGA y EETT/TDR','Derivar expedientes al Jefe','Atender consultas y validar ofertas técnicas'];return {
 'Oficina de administración':['Recepcionar el requerimiento del Área usuaria','Derivarlo a la Unidad de Abastecimiento el mismo día'],
 'DAI':['Recepcionar requerimientos asignados a DAI','Revisar, observar o solicitar no objeción','Conducir indagación y perfeccionamiento'],
 'Unidad de Abastecimiento':['Revisar el requerimiento en 2 días hábiles','Gestionar cotizaciones y cuadro comparativo','Solicitar CCP y emitir OC/OS','Notificar al proveedor con copia al Área usuaria'],
 'Planeamiento y Presupuesto':['Recepcionar solicitud de CCP o previsión','Aprobar certificación presupuestal','Remitir CCP aprobada a la dependencia competente']
 }[state.profile]||[]}
function requirementTable(items){return `<div class="table-wrap"><table class="data-table requirement-table"><thead><tr><th>Expediente</th><th>Requerimiento</th><th>Etapa / estado</th><th>Responsable actual</th><th>DEC</th><th>Acción del perfil</th></tr></thead><tbody>${items.length?items.map(c=>`<tr data-case="${c.id}"><td><span class="case-id">${c.id}</span></td><td class="case-main"><b>${c.title}</b><small>${c.type} · ${c.order}</small></td><td><span class="badge badge--${c.status}">${c.state}</span></td><td>${c.owner}</td><td>${c.reqDec||'Por definir'}</td><td><div class="workflow-actions">${requirementActionButtons(c)}<button class="table-action" data-case="${c.id}" title="Ver expediente">⌕</button></div></td></tr>`).join(''):`<tr><td colspan="6"><div class="empty-state"><h3>Sin requerimientos</h3></div></td></tr>`}</tbody></table></div>`}
function requirementActionButtons(c){
 const technicalLabel={Bien:'EETT · Anexo 1',Servicio:'TDR · Anexo 2',Locación:'TDR · Anexo 3',Consultoría:'TDR · Anexo 4'}[c.type]||'documento técnico';
 const au={draft:['prepare_technical_document',`Elaborar ${technicalLabel}`],technical_draft:['view_technical_document',`Ver y firmar ${technicalLabel}`],technical_signed:c.type==='Locación'?['generate_annex5','Generar propuesta · Anexo 5']:['req_submit','Aprobar y enviar'],annex5_draft:['view_annex5','Ver y firmar Anexo 5'],annex5_signed:['req_submit','Aprobar y enviar'],au_observation_pending:['au_receive_req_obs','Recepcionar observaciones'],au_observation_received:['au_reformulate','Reformular requerimiento'],au_reformulated:['au_resend_req','Reenviar requerimiento'],au_no_objection_pending:['au_receive_noob','Recepcionar solicitud'],au_no_objection_received:['au_decide_noob','Responder no objeción'],au_query_pending:['au_answer_query','Atender consultas'],au_validation_pending:['au_validate_quotes','Validar ofertas técnicas']};
 const oa={oa_pending:['oa_receive_forward_req','Recepción y derivación de requerimiento']};
 const dec={dec_pending:['dec_receive_req','Recepcionar requerimiento'],dec_received:['dec_review_req','Revisar requerimiento'],dec_review:['dec_decide_req','Registrar resultado'],dec_observed:['dec_return_obs','Devolver con observaciones'],dec_improvements:['dec_request_noob','Solicitar no objeción'],dec_noob_answered:['dec_process_noob','Revisar respuesta'],ready_market:['dec_start_market','Solicitar cotizaciones'],quotes_requested:['dec_market_result','Registrar indagación'],dec_query_answered:['dec_resume_market','Continuar indagación'],dec_quotes_validated:['dec_compare_quotes','Evaluar cotizaciones'],ccp_ready:['dec_request_ccp','Solicitar CCP / previsión'],dec_ccp_pending:['dec_receive_ccp','Recepcionar CCP'],dec_ccp_received:['dec_perfect','Perfeccionar contratación'],contract_ready:['dec_issue_order','Emitir OC / OS'],order_issued:['dec_notify','Notificar proveedor y AU']};
 const pp={pp_pending:['pp_receive','Recepcionar solicitud'],pp_received:['pp_approve','Aprobar CCP / previsión'],pp_approved:['pp_send','Remitir CCP aprobada']};
 let action=null;if(state.profile==='Área usuaria'){
  if(isAuJefe()&&c.reqStage==='au_jefe_pending'){
   const labels={req_submit:'Aprobar y enviar requerimiento',au_resend_req:'Aprobar y reenviar requerimiento'};
   action=['jefe_approve_req',labels[c.auPendingAction]||'Aprobar y remitir'];
  }else{
   const base=au[c.reqStage];
   if(base&&isAuEspecialista()&&AU_EXTERNAL_REQ.has(base[0]))action=['derive_to_jefe_req','Derivar al Jefe'];
   else action=base;
  }
 }else if(state.profile==='Oficina de administración')action=oa[c.reqStage];else if(state.profile==='Planeamiento y Presupuesto')action=pp[c.reqStage];else if(state.profile===c.reqDec)action=dec[c.reqStage];
 const edit=state.profile==='Área usuaria'&&c.reqStage==='draft'?`<button class="table-action" data-edit="${c.id}" title="Editar borrador">✎</button><button class="table-action table-action--danger" data-delete="${c.id}" title="Eliminar borrador">×</button>`:'';
 const viewer=c.annex5?`<button class="table-action" data-req-action="view_annex5" data-id="${c.id}" title="Ver Anexos 3 y 5">▤</button>`:c.technicalDoc?`<button class="table-action" data-req-action="view_technical_document" data-id="${c.id}" title="Ver documento técnico">▤</button>`:'';
 return `${action?`<button class="btn btn--workflow" data-req-action="${action[0]}" data-id="${c.id}">${action[1]}</button>`:`<span class="muted action-wait">Sin acción pendiente</span>`}${viewer}${edit}`
}

function openRequirementForm(record=null){
 if(!isAU()){showToast('Sólo el Área usuaria registra el requerimiento inicial');return}const edit=Boolean(record),raw=record?String(record.amount).replace(/[^0-9.]/g,''):'',cmnStatus=record?.reqMeta?.cmnStatus||'yes';const approved=CASES.filter(x=>x.module==='cmn'&&x.cmnAnexo4&&(x.cmnAnexo4Signature||x.cmnStage==='completed'));
 $('#caseDialogBody').innerHTML=`<div class="case-detail-head"><span class="eyebrow">Área usuaria · Elaboración</span><h2>${edit?'Editar':'Nuevo'} requerimiento</h2><p>Registra la necesidad, acredita su condición en el CMN y luego elabora el formato técnico correspondiente.</p></div><div class="case-detail-body"><form id="requirementForm" class="form-grid"><div class="form-field form-field--full"><label>Denominación</label><input name="title" required value="${escapeHtml(record?.title||'')}"></div><div class="form-field"><label>Objeto</label><select name="type">${['Bien','Servicio','Consultoría','Locación'].map(x=>`<option ${record?.type===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label>Dependencia competente</label><select name="reqDec"><option ${record?.reqDec==='Dependencia contrataciones'?'selected':''}>Dependencia contrataciones</option><option ${record?.reqDec==='DAI'?'selected':''}>DAI</option></select></div><div class="form-field"><label>Disponibilidad presupuestal</label><select name="budget"><option>Sí</option><option>No - requiere habilitación</option></select></div><div class="form-field"><label>¿Se encuentra incluido en el CMN?</label><select name="cmnStatus" id="cmnStatus"><option value="yes" ${cmnStatus==='yes'?'selected':''}>Sí</option><option value="no" ${cmnStatus==='no'?'selected':''}>No</option></select></div><div class="form-field form-field--full" id="cmnYesBlock"><label>Anexo N.° 01 del CMN firmado</label><input type="file" name="cmnAnnex1" accept=".pdf,.p7s"><small>Adjunte el documento que acredita la programación.</small></div><div class="form-field form-field--full" id="cmnNoBlock"><div class="sso-note"><span>!</span><p><b>La necesidad no está incluida en el CMN</b><br>Genere la modificación en Gestión CMN y seleccione su Anexo 4 aprobado.</p></div><button type="button" class="btn btn--outline" id="goToCmn">Ir a Gestión CMN</button><label>Anexo 4 CMN generado</label><select name="linkedCmn"><option value="">Seleccione un documento aprobado</option>${approved.map(x=>`<option value="${x.id}" ${record?.reqMeta?.linkedCmn===x.id?'selected':''}>${x.id} · ${escapeHtml(x.cmnAnexo4.requestNumber||x.order)}</option>`).join('')}</select><label>O adjunte el Anexo 4 firmado</label><input type="file" name="cmnAnnex4" accept=".pdf,.p7s"></div><div class="form-field"><label>¿Es ATE?</label><select name="ate"><option>No</option><option>Sí</option></select></div><div class="form-field"><label>Monto estimado (S/)</label><input name="amount" type="number" min="0" required value="${raw}"></div><div class="form-field"><label>Código de pedido SIGA</label><input name="order" required value="${escapeHtml(record?.order||'REQ-2026-')}"></div><div class="form-field"><label>RUC referencial</label><input name="ruc" pattern="[0-9]{11}" maxlength="11" required value="${escapeHtml(record?.ruc||'20612345678')}"></div><div class="form-field"><label>Plazo de atención</label><input name="due" required value="${escapeHtml(record?.due||'10 días hábiles')}"></div><div class="form-field form-field--full"><label>Sustento de la necesidad</label><textarea name="description" required>${escapeHtml(record?.description||'')}</textarea></div><div class="form-field form-field--full"><label>Pedido SIGA y sustentos complementarios</label><input type="file" multiple></div><div class="form-actions"><button type="button" class="btn btn--outline" data-close-record>Cancelar</button><button class="btn btn--primary">Guardar borrador</button></div></form></div>`;
 const toggle=()=>{const no=$('#cmnStatus').value==='no';$('#cmnYesBlock').hidden=no;$('#cmnNoBlock').hidden=!no};$('#cmnStatus').addEventListener('change',toggle);toggle();$('#goToCmn').addEventListener('click',()=>{$('#caseDialog').close();navigate('cmn')});$('[data-close-record]').addEventListener('click',()=>$('#caseDialog').close());$('#requirementForm').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.currentTarget),status=String(d.get('cmnStatus'));if(status==='no'&&!d.get('linkedCmn')&&!d.get('cmnAnnex4')?.name){showToast('Seleccione o adjunte el Anexo 4 CMN firmado');return}const values={title:String(d.get('title')),type:String(d.get('type')),reqDec:String(d.get('reqDec')),amount:formatMoney(Number(d.get('amount'))),order:String(d.get('order')),ruc:String(d.get('ruc')),due:String(d.get('due')),description:String(d.get('description')),reqMeta:{budget:d.get('budget'),cmnStatus:status,linkedCmn:String(d.get('linkedCmn')||''),ate:d.get('ate'),cmnEvidence:status==='yes'?'Anexo 01 CMN':'Anexo 04 CMN'}};if(record)Object.assign(record,values);else CASES.unshift({id:`EXP-2026-${String(nextCaseNumber++).padStart(5,'0')}`,module:'requirement',state:'Borrador · documento técnico pendiente',status:'info',owner:'Área usuaria',progress:8,reqStage:'draft',reqHistory:[{title:'Borrador registrado y condición CMN acreditada',detail:`Área usuaria · ${new Date().toLocaleString('es-PE')}`}],...values});$('#caseDialog').close();render();showToast(edit?'Requerimiento actualizado.':'Requerimiento registrado; elabore ahora su documento técnico.')});$('#caseDialog').showModal()
}

function technicalDocumentConfig(type){return {Bien:{annex:'1',name:'ESPECIFICACIONES TÉCNICAS PARA LA CONTRATACIÓN DE BIENES',pages:'21–26',specific:['Características técnicas del bien','Condiciones de operación','Embalaje, transporte y seguros','Garantía comercial','Instalación, capacitación y soporte']},Servicio:{annex:'2',name:'TÉRMINOS DE REFERENCIA PARA LA CONTRATACIÓN DE SERVICIOS',pages:'27–31',specific:['Descripción y actividades del servicio','Prestaciones accesorias','Entregables','Requisitos y recursos del proveedor','Seguros']},Locación:{annex:'3',name:'TÉRMINOS DE REFERENCIA PARA LOCACIÓN DE SERVICIOS',pages:'32–37',specific:['Marco legal','Actividades del locador','Entregables','Formación académica y capacitación','Experiencia general y específica']},Consultoría:{annex:'4',name:'TÉRMINOS DE REFERENCIA PARA LA CONTRATACIÓN DE CONSULTORÍAS',pages:'38–41',specific:['Alcances y descripción de la consultoría','Perfil del consultor','Equipamiento e infraestructura','Entregables','Recursos provistos por el consultor']}}[type]}
function openTechnicalDocumentForm(c){if(!isAU()){showToast('Sólo el Área usuaria elabora el documento técnico');return}const cfg=technicalDocumentConfig(c.type),a=c.technicalDoc||{},today=new Date().toISOString().slice(0,10);if(!cfg){showToast('Seleccione un objeto válido');return}$('#caseDialogBody').innerHTML=`<div class="case-detail-head"><span class="eyebrow">Requerimiento · ${escapeHtml(c.type)}</span><h2>Anexo N.° ${cfg.annex} · ${cfg.name}</h2><p>Formato basado en las páginas ${cfg.pages} de la Directiva N.° 002-2026-ANIN.</p></div><div class="case-detail-body"><form id="technicalForm" class="form-grid"><div class="form-field"><label>Fecha</label><input type="date" name="date" required value="${escapeHtml(a.date||today)}"></div><div class="form-field"><label>Unidad de organización</label><input name="orgUnit" required value="${escapeHtml(a.orgUnit||'')}"></div><div class="form-field"><label>Actividad operativa</label><input name="operativeActivity" required value="${escapeHtml(a.operativeActivity||'')}"></div><div class="form-field"><label>Meta presupuestaria</label><input name="budgetGoal" required value="${escapeHtml(a.budgetGoal||'')}"></div><div class="form-field form-field--full"><label>Denominación de la contratación</label><input name="denomination" required value="${escapeHtml(a.denomination||c.title)}"></div><div class="form-field form-field--full"><label>Finalidad pública</label><textarea name="publicPurpose" required>${escapeHtml(a.publicPurpose||'')}</textarea></div><div class="form-field form-field--full"><label>Objetivo de la contratación</label><textarea name="objective" required>${escapeHtml(a.objective||'')}</textarea></div><div class="form-field form-field--full"><label>Justificación de la necesidad</label><textarea name="justification" required>${escapeHtml(a.justification||c.description||'')}</textarea></div>${cfg.specific.map((label,i)=>`<div class="form-field form-field--full"><label>${label}</label><textarea name="specific_${i}" ${i<3?'required':''}>${escapeHtml(a.specific?.[i]||'')}</textarea></div>`).join('')}<div class="form-field"><label>Lugar de ejecución / entrega</label><input name="place" required value="${escapeHtml(a.place||'')}"></div><div class="form-field"><label>Plazo</label><input name="term" required value="${escapeHtml(a.term||c.due)}"></div><div class="form-field form-field--full"><label>Área que otorga la conformidad</label><input name="conformityArea" required value="${escapeHtml(a.conformityArea||'')}"></div><div class="form-field form-field--full"><label>Forma y condiciones de pago</label><textarea name="payment" required>${escapeHtml(a.payment||'')}</textarea></div><div class="form-field"><label>Nombre del firmante</label><input name="signerName" required value="${escapeHtml(a.signerName||'María Torres')}"></div><div class="form-field"><label>Cargo / Área usuaria</label><input name="signerRole" required value="${escapeHtml(a.signerRole||'Responsable del Área usuaria')}"></div><div class="form-actions"><button type="button" class="btn btn--outline" data-close-record>Cancelar</button><button class="btn btn--primary">Generar vista previa</button></div></form></div>`;$('[data-close-record]').addEventListener('click',()=>$('#caseDialog').close());$('#technicalForm').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.currentTarget);c.technicalDoc={type:c.type,annex:cfg.annex,name:cfg.name,pages:cfg.pages,date:String(d.get('date')),orgUnit:String(d.get('orgUnit')),operativeActivity:String(d.get('operativeActivity')),budgetGoal:String(d.get('budgetGoal')),denomination:String(d.get('denomination')),publicPurpose:String(d.get('publicPurpose')),objective:String(d.get('objective')),justification:String(d.get('justification')),specific:cfg.specific.map((_,i)=>String(d.get(`specific_${i}`)||'')),specificLabels:cfg.specific,place:String(d.get('place')),term:String(d.get('term')),conformityArea:String(d.get('conformityArea')),payment:String(d.get('payment')),signerName:String(d.get('signerName')),signerRole:String(d.get('signerRole'))};$('#caseDialog').close();applyRequirementTransition(c,'technical_draft',`${cfg.name} generado, pendiente de firma`,'Área usuaria',`Anexo ${cfg.annex} generado`);openTechnicalDocumentViewer(c)});$('#caseDialog').showModal()}
function technicalSignature(c){return c.technicalSignature?`<div class="digital-signature"><span>✓</span><p><b>Firmado digitalmente</b><br>${escapeHtml(c.technicalSignature.name)} · ${escapeHtml(c.technicalSignature.role)}<br>${escapeHtml(c.technicalSignature.date)}<br>SHA-256: ${escapeHtml(c.technicalSignature.hash)}</p></div>`:''}
function renderTechnicalDocument(c){const a=c.technicalDoc||{};return `<div class="annex-document"><article class="annex-page"><div class="annex-title"><b>ANEXO N.° ${annexText(a.annex,'')}</b><strong>${annexText(a.name,'')}</strong></div><div class="annex-page-number">Página 1 de 3</div><table class="annex-meta"><tr><th>Fecha</th><td>${annexText(a.date,'')}</td></tr><tr><th>Unidad de organización</th><td>${annexText(a.orgUnit,'')}</td></tr><tr><th>Actividad operativa</th><td>${annexText(a.operativeActivity,'')}</td></tr><tr><th>Meta presupuestaria</th><td>${annexText(a.budgetGoal,'')}</td></tr><tr><th>Denominación</th><td>${annexText(a.denomination,c.title)}</td></tr></table>${annexSection('I','FINALIDAD PÚBLICA',annexText(a.publicPurpose,''))}${annexSection('II','OBJETIVO DE LA CONTRATACIÓN',annexText(a.objective,''))}${annexSection('III','JUSTIFICACIÓN DE LA NECESIDAD',annexText(a.justification,''))}${technicalSignature(c)}</article><article class="annex-page"><div class="annex-page-number">Página 2 de 3</div>${(a.specificLabels||[]).map((x,i)=>annexSection(String(i+4),x.toUpperCase(),annexText(a.specific?.[i],''),i<3)).join('')}${technicalSignature(c)}</article><article class="annex-page"><div class="annex-page-number">Página 3 de 3</div>${annexSection('','LUGAR Y PLAZO',`<b>Lugar:</b> ${annexText(a.place,'')}<br><b>Plazo:</b> ${annexText(a.term,'')}`)}${annexSection('','CONFORMIDAD',annexText(a.conformityArea,''))}${annexSection('','FORMA Y CONDICIONES DE PAGO',annexText(a.payment,''))}${annexSection('','CLÁUSULAS CONTRACTUALES','Se incorporan las reglas de confidencialidad, penalidades, anticorrupción, resolución contractual y solución de controversias previstas por la Directiva.')}<div class="annex-manual-sign"><b>(Firma digital)</b><strong>${annexText(a.signerName,'')}</strong><span>${annexText(a.signerRole,'')}</span></div>${technicalSignature(c)}</article></div>`}
function openTechnicalDocumentViewer(c){if(!c.technicalDoc){showToast('Primero genere el documento técnico');return}const signed=Boolean(c.technicalSignature),canSign=state.profile==='Área usuaria'&&c.reqStage==='technical_draft';$('#caseDialogBody').innerHTML=`<div class="case-detail-head annex-view-head"><div><span class="eyebrow">Documento técnico generado</span><h2>Anexo N.° ${c.technicalDoc.annex} · ${c.type}</h2><p>${signed?'Firmado digitalmente':'Borrador pendiente de firma'}</p></div><span class="badge badge--${signed?'success':'warning'}">${signed?'Firmado':'Borrador'}</span></div><div class="case-detail-body annex-viewer"><div class="annex-view-toolbar"><button class="btn btn--outline" data-export="pdf">Imprimir / Guardar PDF</button>${canSign?`<button class="btn btn--primary" data-req-action="sign_technical_document" data-id="${c.id}">Firmar digitalmente</button>`:''}</div>${renderTechnicalDocument(c)}</div>`;$('#caseDialog').showModal()}
function signTechnicalDocument(c){const now=new Date(),a=c.technicalDoc;c.technicalSignature={name:a.signerName,role:a.signerRole,date:now.toLocaleString('es-PE'),hash:fakeDocumentHash(`${c.id}|technical|${JSON.stringify(a)}|${now.toISOString()}`)};applyRequirementTransition(c,'technical_signed',`${a.name} firmado`,'Área usuaria',`Anexo ${a.annex} firmado digitalmente`);openTechnicalDocumentViewer(c)}
function openAnnex5Form(c){if(c.type!=='Locación'||!c.technicalSignature){showToast('El Anexo 5 se habilita después de firmar el TDR de Locación');return}const a=c.annex5||{};$('#caseDialogBody').innerHTML=`<div class="case-detail-head"><span class="eyebrow">Locación de servicios</span><h2>Anexo N.° 5 · Propuesta del Área usuaria</h2><p>Registre al proveedor propuesto para el TDR de Locación firmado.</p></div><div class="case-detail-body"><form id="annex5Form" class="form-grid"><div class="form-field"><label>Área usuaria</label><input name="userArea" required value="${escapeHtml(a.userArea||c.technicalDoc.orgUnit)}"></div><div class="form-field"><label>Nombres del proveedor propuesto</label><input name="provider" required value="${escapeHtml(a.provider||'')}"></div><div class="form-field"><label>RUC</label><input name="ruc" pattern="[0-9]{11}" maxlength="11" required value="${escapeHtml(a.ruc||c.ruc)}"></div><div class="form-field"><label>DNI</label><input name="dni" pattern="[0-9]{8}" maxlength="8" required value="${escapeHtml(a.dni||'')}"></div><div class="form-field"><label>Correo electrónico</label><input type="email" name="email" required value="${escapeHtml(a.email||'')}"></div><div class="form-field"><label>Celular</label><input name="phone" required value="${escapeHtml(a.phone||'')}"></div><div class="form-field"><label>Monto mensual S/</label><input type="number" name="monthly" min="0" required value="${escapeHtml(a.monthly||'')}"></div><div class="form-field"><label>Monto total S/</label><input type="number" name="total" min="0" required value="${escapeHtml(a.total||'')}"></div><div class="form-field"><label>Plazo (días)</label><input type="number" name="days" min="1" required value="${escapeHtml(a.days||'')}"></div><div class="form-field"><label>Tipo de registro</label><input name="registryType" required value="${escapeHtml(a.registryType||'Nuevo')}"></div><div class="form-field"><label>Orden SIGA</label><input name="siga" required value="${escapeHtml(a.siga||c.order)}"></div><div class="form-field"><label>Firmante del Área usuaria</label><input name="signerName" required value="${escapeHtml(a.signerName||c.technicalDoc.signerName)}"></div><div class="form-actions"><button type="button" class="btn btn--outline" data-close-record>Cancelar</button><button class="btn btn--primary">Generar Anexo 5</button></div></form></div>`;$('[data-close-record]').addEventListener('click',()=>$('#caseDialog').close());$('#annex5Form').addEventListener('submit',e=>{e.preventDefault();c.annex5=Object.fromEntries([...new FormData(e.currentTarget).entries()].map(([k,v])=>[k,String(v)]));$('#caseDialog').close();applyRequirementTransition(c,'annex5_draft','Anexo 5 generado, pendiente de firma','Área usuaria','Propuesta del Área usuaria generada');openAnnex5Viewer(c)});$('#caseDialog').showModal()}
