function annex5ProposalRow(p){return `<tr><td class="annex5-row-number"></td><td>${escapeHtml(p.provider)}</td><td>${escapeHtml(p.ruc)}</td><td>${escapeHtml(p.dni)}</td><td>${escapeHtml(p.email)}</td><td>${escapeHtml(p.phone)}</td><td>S/ ${escapeHtml(p.monthly)}</td><td>S/ ${escapeHtml(p.total)}</td><td>${escapeHtml(p.days)}</td><td>${escapeHtml(p.registryType)}</td><td><button type="button" class="table-action table-action--danger annex5-remove-proposal" title="Eliminar propuesta" aria-label="Eliminar propuesta">×</button>${Object.entries(p).map(([k,v])=>`<input type="hidden" name="proposal_${k}" value="${escapeHtml(v)}">`).join('')}</td></tr>`}
function collectAnnex5Proposals(d){const fields=['provider','ruc','dni','email','phone','monthly','total','days','registryType'],values=Object.fromEntries(fields.map(k=>[k,d.getAll(`proposal_${k}`)]));return values.provider.map((_,i)=>Object.fromEntries(fields.map(k=>[k,String(values[k][i]||'')]))) }
function addAnnex5ProposalFromCard(){const card=$('#annex5ProposalCapture'),body=$('#annex5ProposalBody');if(!card||!body)return;const inputs=[...card.querySelectorAll('input')],empty=inputs.find(input=>!input.value.trim());if(empty){showToast('Complete todos los datos de la propuesta antes de agregarla');empty.focus();return}const invalid=inputs.find(input=>!input.checkValidity());if(invalid){invalid.reportValidity();return}const p={provider:$('#proposalProvider').value.trim(),ruc:$('#proposalRuc').value.trim(),dni:$('#proposalDni').value.trim(),email:$('#proposalEmail').value.trim(),phone:$('#proposalPhone').value.trim(),monthly:$('#proposalMonthly').value.trim(),total:$('#proposalTotal').value.trim(),days:$('#proposalDays').value.trim(),registryType:$('#proposalRegistryType').value.trim()};body.insertAdjacentHTML('beforeend',annex5ProposalRow(p));inputs.forEach(input=>input.value=input.id==='proposalRegistryType'?'Nuevo':'');refreshAnnex5ProposalTable();showToast('Propuesta agregada al Anexo 5')}
function refreshAnnex5ProposalTable(){const body=$('#annex5ProposalBody');if(!body)return;const rows=[...body.querySelectorAll('tr')];rows.forEach((row,i)=>row.querySelector('.annex5-row-number').textContent=String(i+1));const empty=$('#annex5ProposalEmpty');if(empty)empty.hidden=rows.length>0;const count=$('#annex5ProposalCount');if(count)count.textContent=`${rows.length} propuesta(s) registrada(s)`;$('#annex5ProposalCapture')?.querySelectorAll('input').forEach(input=>input.required=false)}

function requirementActionButtons(c){
  const technicalLabel={Bien:'EETT · Anexo 1',Servicio:'TDR · Anexo 2',Locación:'TDR · Anexo 3',Consultoría:'TDR · Anexo 4'}[c.type]||'documento técnico';
  const au={draft:c.type==='Locación'?['generate_annex5','Generar propuesta · Anexo 5']:['prepare_technical_document',`Elaborar ${technicalLabel}`],annex5_draft:['view_annex5','Ver y firmar Anexo 5'],annex5_signed:['prepare_technical_document','Elaborar TDR · Anexo 3'],technical_draft:['view_technical_document',`Ver y firmar ${technicalLabel}`],technical_signed:['req_submit','Aprobar y enviar'],au_observation_pending:['au_receive_req_obs','Recepcionar observaciones'],au_observation_received:['au_reformulate','Subsanar requerimiento'],au_reformulated:['au_resend_req','Reenviar requerimiento'],au_no_objection_pending:['au_receive_noob','Recepcionar solicitud'],au_no_objection_received:['au_decide_noob','Responder no objeción'],au_query_pending:['au_answer_query','Atender consultas'],au_validation_pending:['au_validate_quotes',c.type==='Locación'?'Validar cotización técnica':'Validar ofertas técnicas']};
  const oa={oa_pending:['oa_receive_forward_req','Recepción y derivación de requerimiento']};
  const dec={dec_pending:['dec_receive_req','Recepcionar requerimiento'],dec_received:['dec_review_req','Revisar requerimiento'],dec_review:['dec_decide_req','Registrar resultado'],dec_observed:['dec_return_obs','Devolver con observaciones'],dec_improvements:['dec_request_noob','Solicitar no objeción'],dec_noob_answered:['dec_process_noob','Revisar respuesta'],ready_market:['dec_start_market',c.type==='Locación'?'Solicitar cotización':'Solicitar cotizaciones'],quotes_requested:['dec_market_result','Registrar indagación'],dec_query_answered:['dec_resume_market','Continuar indagación'],dec_quotes_validated:['dec_compare_quotes',c.type==='Locación'?'Evaluar cotización':'Evaluar cotizaciones'],ccp_ready:['dec_request_ccp','Solicitar CCP / previsión'],dec_ccp_pending:['dec_receive_ccp','Recepcionar CCP'],dec_ccp_received:['dec_perfect','Perfeccionar contratación'],contract_ready:['dec_issue_order','Emitir OC / OS'],order_issued:['dec_notify','Notificar proveedor y AU']};
  const pp={pp_pending:['pp_receive','Recepcionar solicitud'],pp_received:['pp_approve','Aprobar CCP / previsión'],pp_approved:['pp_send','Remitir CCP aprobada']};
  let action=null;if(state.profile==='Área usuaria'){if(isAuJefe()&&c.reqStage==='au_jefe_pending'){const labels={req_submit:'Aprobar y enviar requerimiento',au_resend_req:'Aprobar y reenviar requerimiento'};action=['jefe_approve_req',labels[c.auPendingAction]||'Aprobar y remitir']}else{const base=au[c.reqStage];if(base&&isAuEspecialista()&&AU_EXTERNAL_REQ.has(base[0]))action=['derive_to_jefe_req','Derivar al Jefe'];else action=base}}else if(state.profile==='Oficina de administración')action=oa[c.reqStage];else if(state.profile==='Planeamiento y Presupuesto')action=pp[c.reqStage];else if(state.profile===c.reqDec)action=dec[c.reqStage];
  const edit=state.profile==='Área usuaria'&&c.reqStage==='draft'?`<button class="table-action" data-edit="${c.id}" title="Editar borrador">✎</button><button class="table-action table-action--danger" data-delete="${c.id}" title="Eliminar borrador">×</button>`:'';
  const viewers=`<button class="table-action annex-view-button" data-req-action="view_requirement" data-id="${c.id}" title="Ver formulario del requerimiento"><span aria-hidden="true">◉</span><small>REQ</small></button>${c.annex5?`<button class="table-action annex-view-button" data-req-action="view_annex5" data-id="${c.id}" title="Abrir visor del Anexo 5"><span aria-hidden="true">◉</span><small>A5</small></button>`:''}${c.technicalDoc?`<button class="table-action annex-view-button" data-req-action="view_technical_document" data-id="${c.id}" title="Abrir visor del Anexo ${c.technicalDoc.annex}"><span aria-hidden="true">◉</span><small>A${c.technicalDoc.annex}</small></button>`:''}`;
  return `${action?`<button class="btn btn--workflow" data-req-action="${action[0]}" data-id="${c.id}">${action[1]}</button>`:`<span class="muted action-wait">Sin acción pendiente</span>`}${viewers}${edit}`
}

