function handleAction(action){
 const newModule={'new-cmn':'cmn','new-requirement':'requirement','new-payment':'payment','new-execution':'execution','new-modification':'modification','new-resolution':'resolution'}[action];
 if(newModule){if(newModule==='cmn')openCmnAnexo3Form();else if(newModule==='requirement')openRequirementForm();else if(newModule==='payment')openPaymentForm();else if(newModule==='execution')openExecutionForm();else if(newModule==='modification')openModificationForm();else if(newModule==='resolution')openResolutionForm();else openRecordForm(newModule);return}
 const templates={
  conformity:['Acta de Conformidad · Anexo N.° 11',[['Orden o contrato','text','OS-000172'],['Prestación','text','Consultoría para expediente técnico'],['¿Existen observaciones?','select','No|Sí'],['Días de retraso','number','0'],['Otras penalidades','text','No corresponde']]],
  penalty:['Determinación de penalidades · Anexo N.° 10',[['Monto vigente','number','48500'],['Plazo del entregable (días)','number','30'],['Días de atraso','number','2'],['Penalidad calculada','text','S/ 646.67 (simulado)']]],
  extension:['Evaluar ampliación de plazo',[['Fecha fin del hecho generador','date',''],['Fecha de solicitud','date',''],['Días solicitados','number',''],['Sustento técnico','textarea',''],['Resultado','select','Procedente|Improcedente']]]
 };
 const fallback=['Registrar actuación',[['Expediente','text','EXP-2026-'],['Comentario','textarea','Detalle la actuación o adjunte el documento correspondiente']]];
 openForm(...(templates[action]||fallback));
}

