 requirement:{title:'Registro de Requerimiento a Notificación',types:['Bien','Servicio','Consultoría','Locación'],states:['En elaboración','En autorización','En revisión','Subsanación requerida','Indagación de mercado','CCP pendiente','Perfeccionamiento','Notificado'],extra:'Documento técnico',extraOptions:['EETT - Anexo 1','TDR - Anexo 2','TDR persona natural - Anexo 3','TDR consultoría - Anexo 4']},
 payment:{title:'Registro de Pago',types:['Bien','Servicio','Consultoría','Locación'],states:['Conformidad recibida','Control de pagos','Control previo','Observado','Devengado aprobado','Giro registrado'],extra:'Número de pago',extraOptions:['Pago único','Pago N.° 1','Pago N.° 2','Pago final']},
